    25  #define FU_U2F_FIRMWARE_TAG_VERSION     0x9fc7bc /* semver of firmware file (UTF-8) */
    26  #define FU_U2F_FIRMWARE_TAG_DESCRIPTION 0x650d9d /* description of device (UTF-8) */
    27  #define FU_U2F_FIRMWARE_TAG_PAGE_SZ     0x0be9f7 /* page size of target device (uint32_t) */
    28  #define FU_U2F_FIRMWARE_TAG_SHA1        0xb46db0 /* SHA-2 checksum of firmware */
