    31  static gboolean
    32  fu_uf2_firmware_parse_chunk(FuUf2Firmware *self, FuChunk *chk, GByteArray *tmp, GError **error)
    33  {
    34          gsize bufsz = fu_chunk_get_data_sz(chk);
    35          const guint8 *buf = fu_chunk_get_data(chk);
    36          guint32 flags = 0;
    37          guint32 datasz = 0;
    38          g_autoptr(GByteArray) st = NULL;
    39
    40          /* parse */
    41          st = fu_struct_uf2_parse(fu_chunk_get_data(chk),
    42                                   fu_chunk_get_data_sz(chk),
    43                                   0, /* offset */
    44
    45                                   error);
    46          if (st == NULL)
    47                  return FALSE;
    48          flags = fu_struct_uf2_get_flags(st);
    49          if (flags & FU_UF2_FIRMWARE_BLOCK_FLAG_IS_CONTAINER) {
    50                  g_set_error_literal(error,
    51                                      FWUPD_ERROR,
    52                                      FWUPD_ERROR_NOT_SUPPORTED,
    53                                      "container U2F firmware not supported");
    54                  return FALSE;
    55          }
    56          datasz = fu_struct_uf2_get_payload_size(st);
    57          if (datasz > 476) {
    58                  g_set_error(error,
    59                              FWUPD_ERROR,
    60                              FWUPD_ERROR_INVALID_DATA,
    61                              "data size impossible got 0x%08x",
    62                              datasz);
    63                  return FALSE;
    64          }
    65          if (fu_struct_uf2_get_block_no(st) != fu_chunk_get_idx(chk)) {
