    67                              FWUPD_ERROR,
    68                              FWUPD_ERROR_INVALID_DATA,
    69                              "block count invalid, expected 0x%04x and got 0x%04x",
    70                              fu_chunk_get_idx(chk),
    71                              fu_struct_uf2_get_block_no(st));
    72                  return FALSE;
    73          }
