    99          if (flags & FU_UF2_FIRMWARE_BLOCK_FLAG_HAS_MD5) {
   100                  if (datasz < 24) {
   101                          g_set_error_literal(error,
   102                                              FWUPD_ERROR,
   103                                              FWUPD_ERROR_INVALID_DATA,
   104                                              "not enough space for MD5 checksum");
   105                          return FALSE;
   106                  }
   107          }
   108          if (flags & FU_UF2_FIRMWARE_BLOCK_FLAG_HAS_EXTENSION_TAG) {
   109                  gsize offset = FU_STRUCT_UF2_OFFSET_DATA;
