   111                          guint8 sz = 0;
   112                          guint32 tag = 0;
   113
   114                          /* [SZ][TAG][TAG][TAG][TAG][DATA....] */
   115                          if (!fu_memread_uint8_safe(buf, bufsz, offset, &sz, error))
   116                                  return FALSE;
   117                          if (sz < 4) {
   118                                  g_set_error_literal(error,
   119                                                      FWUPD_ERROR,
   120                                                      FWUPD_ERROR_INVALID_DATA,
   121                                                      "invalid extension tag size");
   122                                  return FALSE;
   123                          }
   124                          if (!fu_memread_uint32_safe(buf,
   125                                                      bufsz,
   126                                                      offset,
   127                                                      &tag,
   128                                                      G_LITTLE_ENDIAN,
   129                                                      error))
   130                                  return FALSE;
   131                          tag &= 0xFFFFFF;
   132                          if (tag == FU_U2F_FIRMWARE_TAG_VERSION) {
   133                                  g_autofree gchar *utf8buf = g_malloc0(sz);
   134                                  if (!fu_memcpy_safe((guint8 *)utf8buf,
   135                                                      sz,
   136                                                      0x0, /* dst */
   137                                                      buf,
   138                                                      bufsz,
   139                                                      offset + 0x4, /* src */
   140                                                      sz - 4,
   141                                                      error))
   142                                          return FALSE;
   143                                  fu_firmware_set_version(FU_FIRMWARE(self), utf8buf);
