   145                                  g_autofree gchar *utf8buf = g_malloc0(sz);
   146                                  if (!fu_memcpy_safe((guint8 *)utf8buf,
   147                                                      sz,
   148                                                      0x0, /* dst */
   149                                                      buf,
   150                                                      bufsz,
   151                                                      offset + 0x4, /* src */
   152                                                      sz - 4,
   153                                                      error))
   154                                          return FALSE;
   155                                  fu_firmware_set_id(FU_FIRMWARE(self), utf8buf);
   156                          } else {
   157                                  if (g_getenv("FWUPD_FUZZER_RUNNING") == NULL)
   158                                          g_warning("unknown tag 0x%06x", tag);
   159                          }
   160
   161                          /* next! */
   162                          offset += sz;
   163                  }
   164          }
   165
   166          /* success */
   167          return TRUE;
   168  }
