   170  static gboolean
   171  fu_uf2_firmware_parse(FuFirmware *firmware,
   172                        GInputStream *stream,
   173                        gsize offset,
   174                        FwupdInstallFlags flags,
   175                        GError **error)
   176  {
   177          FuUf2Firmware *self = FU_UF2_FIRMWARE(firmware);
   178          g_autoptr(GByteArray) tmp = g_byte_array_new();
   179          g_autoptr(GBytes) blob = NULL;
   180          g_autoptr(FuChunkArray) chunks = NULL;
   181
   182          /* read in fixed sized chunks */
   183          chunks = fu_chunk_array_new_from_stream(stream, offset, 512, error);
   184          if (chunks == NULL)
   185                  return FALSE;
   186          for (guint i = 0; i < fu_chunk_array_length(chunks); i++) {
   187                  g_autoptr(FuChunk) chk = NULL;
   188
   189                  /* prepare chunk */
   190                  chk = fu_chunk_array_index(chunks, i, error);
   191                  if (chk == NULL)
   192                          return FALSE;
   193                  if (!fu_uf2_firmware_parse_chunk(self, chk, tmp, error))
   194                          return FALSE;
   195          }
   196
   197          /* success */
   198          blob = g_bytes_new(tmp->data, tmp->len);
   199          fu_firmware_set_bytes(firmware, blob);
   200          return TRUE;
   201  }
   202
   203  static GByteArray *
   204  fu_uf2_firmware_write_chunk(FuUf2Firmware *self, FuChunk *chk, guint chk_len, GError **error)
   205  {
   206          guint32 addr = fu_firmware_get_addr(FU_FIRMWARE(self));
   207          guint32 flags = FU_UF2_FIRMWARE_BLOCK_FLAG_NONE;
   208          g_autoptr(GByteArray) st = fu_struct_uf2_new();
   209
   210          /* optional */
   211          if (fu_firmware_get_idx(FU_FIRMWARE(self)) > 0)
   212                  flags |= FU_UF2_FIRMWARE_BLOCK_FLAG_HAS_FAMILY;
   213
   214          /* offset from base address */
   215          addr += fu_chunk_get_idx(chk) * fu_chunk_get_data_sz(chk);
   216
   217          /* build UF2 packet */
   218          fu_struct_uf2_set_flags(st, flags);
   219          fu_struct_uf2_set_target_addr(st, addr);
   220          fu_struct_uf2_set_payload_size(st, fu_chunk_get_data_sz(chk));

